export function calculateOverageCharge(minutes: number) {
  if (minutes <= 100) return 0;
  return (minutes - 100) * 0.25;
}

function computeTotal(items: number, applyTax = true) {
  const subtotal = items * 20;
  const tax = applyTax ? subtotal * 0.08 : 0;
  if (subtotal > 500) return subtotal * 0.9;
  return subtotal + tax;
}

