function calculateFee(amount: number) {
  if (amount > 1000) return amount * 0.02;
  return amount * 0.01;
}

// Version B
const HIGH_THRESHOLD = 1000;
const HIGH_RATE = 0.02;
const LOW_RATE = 0.01;
function calculateFee(amount: number) {
  if (amount > HIGH_THRESHOLD) return amount * HIGH_RATE;
  return amount * LOW_RATE;
}
